//! 矢量刀路写出：轮廓与规划步骤。

use super::WriterOptions;
use laser_contracts::geometry::Paths;

pub fn write_outline(paths: &Paths, options: &WriterOptions) -> Result<String, &'static str> {
    let scale = options.power_scale.unwrap_or(1000);
    if !options.width_mm.is_finite()
        || !options.height_mm.is_finite()
        || options.width_mm <= 0.0
        || options.height_mm <= 0.0
        || options.power < 0
        || options.power > scale
        || options.feed_rate < 1
    {
        return Err("invalid writer options");
    }
    let mut lines = vec![
        "; Generated by laser-core".to_owned(),
        format!("; GRBL laser mode expected: $30={scale}, $32=1"),
        "G21".into(),
        "G90".into(),
        "G94".into(),
        "G17".into(),
        "G92 X0 Y0 Z0".into(),
        format!("{} S0", options.laser_mode),
        "G0 F3000".into(),
    ];
    let mut current_feed: Option<i32> = None;
    for path in paths {
        if path.is_empty() {
            continue;
        }
        let point = |(x, y): (f64, f64)| -> Result<(f64, f64), &'static str> {
            if !x.is_finite() || !y.is_finite() {
                return Err("path contains non-finite coordinates");
            }
            Ok((x, options.height_mm - y))
        };
        let start = point(path[0])?;
        lines.push(format!("G0 X{:.3} Y{:.3}", start.0, start.1));
        for &vertex in path.iter().skip(1) {
            let (x, y) = point(vertex)?;
            let f_part = if current_feed != Some(options.feed_rate) {
                current_feed = Some(options.feed_rate);
                format!(" F{}", options.feed_rate)
            } else {
                String::new()
            };
            lines.push(format!("G1 X{x:.3} Y{y:.3} S{}{f_part}", options.power));
        }
        if options.auto_close && path.len() > 2 && path.last() != path.first() {
            let f_part = if current_feed != Some(options.feed_rate) {
                current_feed = Some(options.feed_rate);
                format!(" F{}", options.feed_rate)
            } else {
                String::new()
            };
            lines.push(format!(
                "G1 X{:.3} Y{:.3} S{}{f_part}",
                start.0, start.1, options.power
            ));
        }
        lines.push("S0".into());
    }
    lines.extend(["M5".into(), "M2".into()]);
    Ok(lines.join("\n") + "\n")
}

/// 矢量规划输出的一步（坐标与刀路同为 y 向下，写出时翻转）。
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Step {
    /// `G0` 关光空走
    Travel((f64, f64)),
    /// `G1 … S0` 按加工速度关光滑行（过扫描、扫描行里图形之间的空白）
    Coast((f64, f64)),
    /// `G1 … S功率` 出光
    Burn((f64, f64)),
}

/// 按规划步骤写 G-code（2026-11-16，矢量扫描填充的过扫描用 `G1 S0` 而不是 `G0`：
/// 激光头匀速滑过、GRBL 不会因 M3/M4/M5 切换而停顿）。头尾与 [`write_outline`] 相同。
pub fn write_steps(steps: &[Step], options: &WriterOptions) -> Result<String, &'static str> {
    let scale = options.power_scale.unwrap_or(1000);
    if !options.width_mm.is_finite()
        || !options.height_mm.is_finite()
        || options.width_mm <= 0.0
        || options.height_mm <= 0.0
        || options.power < 0
        || options.power > scale
        || options.feed_rate < 1
    {
        return Err("invalid writer options");
    }
    let mut lines = vec![
        "; Generated by laser-core (vector plan)".to_owned(),
        format!("; GRBL laser mode expected: $30={scale}, $32=1"),
        "G21".into(),
        "G90".into(),
        "G94".into(),
        "G17".into(),
        "G92 X0 Y0 Z0".into(),
        format!("{} S0", options.laser_mode),
        "G0 F3000".into(),
    ];
    let mut current_feed: Option<i32> = None;
    let mut burning = false;
    for step in steps {
        let (Step::Travel((x, y)) | Step::Coast((x, y)) | Step::Burn((x, y))) = *step;
        if !x.is_finite() || !y.is_finite() {
            return Err("path contains non-finite coordinates");
        }
        let y = options.height_mm - y;
        let mut feed = || {
            if current_feed != Some(options.feed_rate) {
                current_feed = Some(options.feed_rate);
                format!(" F{}", options.feed_rate)
            } else {
                String::new()
            }
        };
        match step {
            Step::Travel(_) => {
                if burning {
                    lines.push("S0".into());
                    burning = false;
                }
                lines.push(format!("G0 X{x:.3} Y{y:.3}"));
            }
            Step::Coast(_) => {
                burning = false;
                let f = feed();
                lines.push(format!("G1 X{x:.3} Y{y:.3} S0{f}"));
            }
            Step::Burn(_) => {
                burning = true;
                let f = feed();
                lines.push(format!("G1 X{x:.3} Y{y:.3} S{}{f}", options.power));
            }
        }
    }
    if burning {
        lines.push("S0".into());
    }
    lines.extend(["M5".into(), "M2".into()]);
    Ok(lines.join("\n") + "\n")
}
